```typescript
// 响应式列表：手机单列，平板双列
@Entry
@Component
struct ResponsiveGridDemo {
  @State currentBreakpoint: string = 'sm'

  build() {
    // 监听断点变化
    MediaQuery('(min-width: 600vp)').onMatch(() => {
      this.currentBreakpoint = 'md'
    })
    MediaQuery('(max-width: 599vp)').onMatch(() => {
      this.currentBreakpoint = 'sm'
    })

    GridRow({ columns: 12, gutter: { x: 8, y: 8 } }) {
      ForEach([1, 2, 3, 4], (item: number) => {
        GridCol({ span: { xs: 12, sm: 6, md: 4 } }) {
          Text(`Item ${item}`)
            .width('100%')
            .height(80)
            .backgroundColor('#ccc')
            .textAlign(TextAlign.Center)
        }
      })
    }
    .width('100%')
    .padding(16)
  }
}
```

**验证**：在模拟器上切换手机/平板预览，观察 Item 从单列变双列/三列。

