以下是一个简单的 KV 分布式数据库创建与同步示例（ArkTS）：

```typescript
// 导入分布式数据模块
import { distributedKVStore } from '@kit.ArkData';
import { distributedDeviceManager } from '@kit.DistributedServiceKit';
import { BusinessError } from '@kit.BasicServicesKit';

// 1. 获取 KV Manager（需先申请 ohos.permission.DISTRIBUTED_DATASYNC）
const kvManager = distributedKVStore.createKVManager({
  bundleName: 'com.example.myapp',
  userId: '0'
});

// 2. 创建或打开 KV Store
const options: distributedKVStore.Options = {
  createIfMissing: true,
  encrypt: false,
  backup: false,
  kvStoreType: distributedKVStore.KVStoreType.SINGLE_VERSION
};
const kvStore = await kvManager.getKVStore('my_store', options);

// 3. 写入本地数据
await kvStore.put('key_hello', 'value_from_device_a');

// 4. 获取可信设备列表并同步
const deviceManager = distributedDeviceManager.createDeviceManager('com.example.myapp');
const devices = deviceManager.getTrustedDeviceListSync();
if (devices.length > 0) {
  kvStore.sync(devices.map(d => d.networkId), 
    distributedKVStore.SyncMode.PUSH_PULL, 
    (err: BusinessError, result: distributedKVStore.SyncInfo) => {
      if (err) {
        console.error(`Sync failed: ${err.message}`);
      } else {
        console.info(`Sync success, devices: ${JSON.stringify(result.deviceInfos)}`);
      }
    });
}

