```dart
import 'package:flutter/material.dart';

class LazyList extends StatefulWidget {
  @override
  _LazyListState createState() => _LazyListState();
}

class _LazyListState extends State<LazyList> {
  final List<int> _items = List.generate(20, (i) => i);
  final ScrollController _controller = ScrollController();
  bool _isLoading = false;

  @override
  void initState() {
    super.initState();
    _controller.addListener(() {
      if (_controller.position.extentAfter < 200 && !_isLoading) {
        _loadMore();
      }
    });
  }

  Future<void> _loadMore() async {
    setState(() => _isLoading = true);
    await Future.delayed(Duration(seconds: 1));
    setState(() {
      _items.addAll(List.generate(20, (i) => _items.length + i));
      _isLoading = false;
    });
  }

  @override
  Widget build(BuildContext context) {
    return ListView.builder(
      controller: _controller,
      itemCount: _items.length + 1,
      itemBuilder: (context, index) {
        if (index >= _items.length) {
          return Center(child: CircularProgressIndicator());
        }
        return ListTile(title: Text('Item ${_items[index]}'));
      },
    );
  }
}
```

