// 1. shared_preferences 示例
import 'package:shared_preferences/shared_preferences.dart';

Future<void> saveLoginState(bool isLoggedIn) async {
  final prefs = await SharedPreferences.getInstance();
  await prefs.setBool('is_logged_in', isLoggedIn);
}

Future<bool?> loadLoginState() async {
  final prefs = await SharedPreferences.getInstance();
  return prefs.getBool('is_logged_in');
}

// 2. sqflite 示例
import 'package:sqflite/sqflite.dart';

Future<Database> openDb() async {
  return openDatabase(
    'my_app.db',
    version: 1,
    onCreate: (db, version) async {
      await db.execute('''
        CREATE TABLE notes (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          title TEXT,
          content TEXT
        )
      ''');
    },
  );
}

Future<void> insertNote(Database db, String title, String content) async {
  await db.insert('notes', {'title': title, 'content': content});
}

// 3. 文件存储示例
import 'package:path_provider/path_provider.dart';
import 'dart:io';

Future<File> getNotesFile() async {
  final dir = await getApplicationDocumentsDirectory();
  return File('${dir.path}/notes.json');
}

Future<void> writeNotes(String jsonString) async {
  final file = await getNotesFile();
  await file.writeAsString(jsonString);
}
