以下是一个完整的 React Native + TypeScript 网络请求示例，包含 fetch 和 axios 两种方式、错误处理、超时控制与类型定义：

```typescript
// types.ts
interface User {
  id: number;
  name: string;
  email: string;
}

// fetch 方式（带超时）
async function fetchUserWithTimeout(id: number): Promise<User> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 5000); // 5秒超时

  try {
    const response = await fetch(`https://api.example.com/users/${id}`, {
      signal: controller.signal,
    });

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    const data = (await response.json()) as User;
    return data;
  } catch (error) {
    if (error.name === 'AbortError') {
      throw new Error('请求超时，请检查网络');
    }
    throw error;
  } finally {
    clearTimeout(timeout);
  }
}

// axios 方式（更简洁）
import axios from 'axios';

async function fetchUserWithAxios(id: number): Promise<User> {
  try {
    const { data } = await axios.get<User>(
      `https://api.example.com/users/${id}`,
      { timeout: 5000 }
    );
    return data;
  } catch (error) {
    if (axios.isAxiosError(error)) {
      if (error.code === 'ECONNABORTED') {
        throw new Error('请求超时');
      }
      if (error.response) {
        throw new Error(`服务器返回错误: ${error.response.status}`);
      }
    }
    throw new Error('网络连接失败');
  }
}
```

