**场景**：为一个计数器 App 编写一个简单的集成测试，并模拟点击按钮。

**步骤 1**：在 `pubspec.yaml` 中添加依赖：
```yaml
dev_dependencies:
  integration_test:
    sdk: flutter
  flutter_test:
    sdk: flutter
```

**步骤 2**：创建 `integration_test/app_test.dart` 文件：
```dart
import 'package:flutter_test/flutter_test.dart';
import 'package:integration_test/integration_test.dart';
import 'package:my_app/main.dart' as app; // 替换为你的入口文件

void main() {
  IntegrationTestWidgetsFlutterBinding.ensureInitialized();

  testWidgets('完整流程：点击按钮 5 次，计数器显示 5', (tester) async {
    app.main();
    await tester.pumpAndSettle();

    // 找到按钮并点击 5 次
    for (int i = 0; i < 5; i++) {
      await tester.tap(find.byType(FloatingActionButton));
      await tester.pumpAndSettle();
    }

    // 验证文本显示为 '5'
    expect(find.text('5'), findsOneWidget);
  });
}
```

