    <input
      class="input"
      v-model="username"
      placeholder="请输入用户名"
      @input="handleInput"
    />
    <switch :checked="remember" @change="handleRemember" />
    <button type="primary" @click="handleLogin">登录</button>
  </view>
</template>

<script>
export default {
  data() {
    return {
      username: '',
      remember: false,
    };
  },
  methods: {
    handleInput(e) {
      console.log('输入中：', e.detail.value);
    },
    handleRemember(e) {
      this.remember = e.detail.value;
      console.log('记住密码：', this.remember);
    },
    handleLogin() {
      console.log('登录，用户名：', this.username);
    },
  },
};
</script>
```

