// 异步写入（推荐）
uni.setStorage({
  key: 'user_token',
  data: 'abc123xyz',
  success: () => {
    console.log('写入成功');
    // 异步读取
    uni.getStorage({
      key: 'user_token',
      success: (res) => {
        console.log('读取到:', res.data); // 输出: abc123xyz
        // 删除
        uni.removeStorage({
          key: 'user_token',
          success: () => console.log('已删除')
        });
      }
    });
  },
  fail: (err) => {
    console.error('存储失败:', err);
    // 处理超限、权限等错误
  }
});

// 同步写入（数据量小、需立即读取时）
try {
  uni.setStorageSync('theme_color', '#FF6600');
  const color = uni.getStorageSync('theme_color'); // 立即返回
  console.log('同步读取:', color);
} catch (e) {
  console.error('同步存储异常:', e);
}
