**自测题**：写一个函数 `saveUserProfile(user)`，要求：使用异步 API 存储，存储失败时弹出 toast 提示“保存失败”，成功时返回 `true`。

```javascript
function saveUserProfile(user) {
  return new Promise((resolve) => {
    uni.setStorage({
      key: 'user_profile',
      data: user,
      success: () => resolve(true),
      fail: () => {
        uni.showToast({ title: '保存失败', icon: 'none' });
        resolve(false);
      }
    });
  });
}
```

