**场景**：优化一个新闻列表页，减少 setData 次数并验证分包效果。

```javascript
// 错误示范：一次性 setData 全量数据
onLoad() {
  wx.request({
    url: 'https://api.example.com/news',
    success: (res) => {
      this.setData({ newsList: res.data }) // 若 res.data 有 500 条，渲染卡顿
    }
  })
}

// 正确示范：分批渲染 + 仅传增量
Page({
  data: {
    newsList: [],
    page: 1
  },
  onLoad() {
    this.fetchPage(1)
  },
  fetchPage(page) {
    wx.request({
      url: `https://api.example.com/news?page=${page}&size=20`,
      success: (res) => {
        const newItems = res.data.map(item => ({ id: item.id, title: item.title }))
        // 使用 concat 合并，但只 setData 新增部分
        this.setData({
          [`newsList[${this.data.newsList.length}]`]: newItems // 按索引追加
        })
      }
    })
  }
})
```

