    { label: '显示窗口', click: () => { win.show(); win.focus() } },
    { label: '退出', click: () => app.quit() }
  ]))

  // 3. 全局快捷键
  const ok = globalShortcut.register('CommandOrControl+Shift+Y', () => {
    win.show()
    win.focus()
  })
  if (!ok) console.log('快捷键注册失败，可能被占用')

  win.on('close', (e) => {
    // 拦截关闭，隐藏到托盘（典型场景）
    e.preventDefault()
    win.hide()
  })
})

app.on('will-quit', () => {
  globalShortcut.unregisterAll()
})
