     await expect(page.getByTestId('order-amount')).toHaveText(/\$\d+\.\d{2}/);
   });
   ```
3. **语义定位器优先**：`getByRole('button', { name: '查看详情' })` 比 `page.locator('.css-1x2y3z')` 更健壮；若按钮无文本，用 `getByLabel` 或 `getByPlaceholder`。
4. **自动等待**：`click` 和 `toHaveText` 均自动重试，无需 `waitForTimeout`；点击"查看详情"后页面跳转，断言自动等待新页面元素出现。
5. **常见坑**：`auth.json` 含敏感 token，需加入 `.gitignore`；若登录态过期，测试会失败，需定期更新或改用 API 登录预置。
6. **面试小结**：展示对 Playwright 核心 API（storageState、语义定位器、web-first 断言）的综合运用，并说明工程化细节（如 auth 文件管理）。

**核心结论**：核心是"拖拽用原生事件实时更新位置，松手后用 Web Animations API 或 JS 物理模拟实现 spring 回弹"，而不是用 CSS transition（无法模拟 spring 的振荡收敛）。

```vue
<template>
  <div
    class="card"
    :style="{ transform: `translate(${x}px, ${y}px)` }"
    @pointerdown="onDown"
    @pointermove="onMove"
    @pointerup="onUp"
  ></div>
</template>

<script setup>
import { ref } from 'vue'

const x = ref(0)
const y = ref(0)
let startX = 0, startY = 0, originX = 0, originY = 0
let dragging = false

function onDown(e) {
  dragging = true
  originX = x.value
  originY = y.value
  startX = e.clientX
  startY = e.clientY
  e.target.setPointerCapture(e.pointerId)
}

function onMove(e) {
  if (!dragging) return
  x.value = originX + e.clientX - startX
  y.value = originY + e.clientY - startY
}

function onUp() {
  dragging = false
  // 使用 Web Animations API 模拟 spring（stiffness=170, damping=26 近似 iOS 弹簧）
  const anim = el.animate(
    [
      { transform: `translate(${x.value}px, ${y.value}px)` },
      { transform: 'translate(0, 0)' }
    ],
    {
      duration: 500,
      easing: 'cubic-bezier(0.25, 1.5, 0.5, 1)', // 近似 spring 的一次过冲
    }
  )
  anim.onfinish = () => { x.value = 0; y.value = 0 }
}
</script>
```

**关键技术点**：
- 用 Pointer Events 统一鼠标/触摸，`setPointerCapture` 保证拖拽不丢失。
- spring 的精确模拟需引入物理库（如 `@react-spring/web` 或自写 Verlet 积分）；CSS 的 `cubic-bezier` 只能近似一次过冲，多次振荡需 JS。
- 松手时用 `el.animate`（WAAPI）而非 `transition`，因为 WAAPI 支持从当前值动画到目标值且可编程控制 easing。

**常见坑**：直接用 CSS `transition` 加 `cubic-bezier` 模拟 spring，只能产生一次回弹，无法表现真实弹簧的多次衰减振荡；忘记在 `pointerup` 时释放捕获。

**面试小结**：展示"拖拽实时更新 + 松手弹簧回弹"的完整链路，并指出 CSS 与 JS 在物理模拟上的能力边界。

核心是用 `useSyncExternalStore` 订阅媒体查询状态，在 reduce 时跳过动画直接切换，同时用 CSS 变量控制过渡时长。

**分点展开：**
- **订阅媒体查询**：
  ```jsx
  function usePrefersReducedMotion() {
    return useSyncExternalStore(
      (callback) => {
        const mq = window.matchMedia('(prefers-reduced-motion: reduce)');
        mq.addEventListener('change', callback);
        return () => mq.removeEventListener('change', callback);
      },
      () => window.matchMedia('(prefers-reduced-motion: reduce)').matches
    );
  }
  ```
- **组件实现**：
  ```jsx
  function Collapsible({ children }) {
    const [open, setOpen] = useState(false);
    const reduce = usePrefersReducedMotion();

    return (
      <div
        style={{
          transition: reduce ? 'none' : 'height 0.3s ease',
          height: open ? 'auto' : 0,
          overflow: 'hidden'
        }}
      >
        {children}
      </div>
    );
  }
  ```
- **关键点**：`reduce` 时 `transition` 设为 `none`，高度变化瞬时完成；JS 侧无需额外逻辑，因为 CSS 已处理。
- **进阶**：若动画涉及 JS 计算（如滚动位置），需在 `reduce` 时直接跳到最终值，避免 rAF 循环。

**常见坑：**
- 只用 CSS 媒体查询，但 JS 组件内部状态更新仍触发重排，导致闪烁。
- 未使用 `useSyncExternalStore` 导致订阅泄漏或渲染不一致。

**面试小结：**
代码展示 `useSyncExternalStore` 的用法是关键亮点，同时说明"CSS 管视觉、JS 管状态"的协作模式，体现工程化思维。

**核心结论：使用 `map` 渲染列表、条件表达式处理空态、事件绑定传递参数，完整代码如下。**
```jsx
function ItemList({ items }) {
  const handleClick = (item) => {
    console.log(item);
  };

  return (
    <ul>
      {items.length === 0 ? (
        <li>暂无数据</li>
      ) : (
        items.map((item, index) => (
          <li key={index} onClick={() => handleClick(item)}>
            {item}
          </li>
        ))
      )}
    </ul>
  );
}
```
- 空态处理：使用三元表达式 `items.length === 0 ? ... : ...`，因为 JSX 不支持 `if` 语句。
- 列表渲染：`map` 返回 JSX 数组，每个元素需有 `key`（此处用 index，实际生产建议用唯一 id）。
- 事件绑定：`onClick` 接收箭头函数，避免直接 `onClick={handleClick(item)}`（会立即执行）。
- 函数组件：接收 `{ items }` 解构 props，符合纯函数原则。
- 常见坑：忘记 `key` 导致控制台警告；事件绑定直接传参导致页面加载时即执行；空态判断写在 `map` 内部导致渲染空数组。
- 面试小结：本题综合考察 JSX 表达式、列表渲染、事件处理三大核心，回答时主动解释每个决策点，展示编码规范意识。

**核心结论：CJS 按解析后的绝对路径缓存模块，循环依赖时先被加载的模块会拿到尚未执行完的 `module.exports` 对象（即半成品），这是由"运行时同步执行 + 缓存"机制决定的。**

1. **缓存机制**：模块首次被 `require` 时执行并缓存，之后 `require` 同一路径直接返回缓存对象。可通过 `delete require.cache[modulePath]` 强制重新加载。
2. **循环依赖场景**（官方示例）：
   ```js
   // a.js
   exports.done = false;
   const b = require('./b.js');
   console.log('a.js: b.done =', b.done);
   exports.done = true;

   // b.js
   exports.done = false;
   const a = require('./a.js');
   console.log('b.js: a.done =', a.done);  // 输出 false，因为 a.js 还没执行完
   exports.done = true;
   ```
3. **半成品原因**：`a.js` 先执行到 `require('./b.js')` 时，`b.js` 开始执行，`b.js` 中 `require('./a.js')` 发现 `a.js` 在缓存中但**尚未执行完毕**，于是返回当前 `module.exports`（此时只有 `done = false`），这就是半成品。
4. **设计权衡**：CJS 的同步加载决定了无法像 ESM 那样在编译期解决循环依赖问题。ESM 通过活绑定，即使模块未执行完，导入方也能在模块执行后看到最新值。

**常见坑**：在循环依赖中，如果 `b.js` 在 `a.js` 执行完之前就使用 `a` 的导出，可能拿到 `undefined` 或空对象。解决方法是延迟访问（在函数内部使用时再取）或重构依赖关系。

**面试小结**：先讲缓存机制，再用代码演示循环依赖的执行顺序，最后对比 ESM 的活绑定如何规避此问题。

核心结论——race 让"业务请求"与"定时器"竞争，谁先结算谁决定结果，但定时器必须正确 reject 才能触发超时逻辑。

**分点展开：**
- **基础实现**：
  ```js
  function withTimeout(promise, ms) {
    const timeout = new Promise((_, reject) => {
      setTimeout(() => reject(new Error('timeout')), ms);
    });
    return Promise.race([promise, timeout]);
  }
  ```
- **原理**：race 只关心"第一个 settle"，若请求先返回则正常兑现；若定时器先触发则 reject，整体进入错误分支。
- **缺陷 1——定时器泄漏**：若请求先返回，定时器仍在运行，到点后 reject 一个已被忽略的 Promise，造成无意义操作（不会报错但浪费资源）。
  ```js
  // 改进：清除定时器
  function withTimeout(promise, ms) {
    let timer;
    const timeout = new Promise((_, reject) => {
      timer = setTimeout(() => reject(new Error('timeout')), ms);
    });
    return Promise.race([promise, timeout]).finally(() => clearTimeout(timer));
  }
  ```
- **缺陷 2——请求未取消**：超时后底层 fetch 仍在进行，可能产生副作用（如写入操作）。改进：使用 `AbortController` 真正取消请求。
  ```js
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 3000);
  try {
    const res = await fetch(url, { signal: controller.signal });
  } catch (e) {
    if (e.name === 'AbortError') console.log('timeout');
  } finally { clearTimeout(timeoutId); }
  ```
- **缺陷 3——定时器 resolve 陷阱**：若定时器写的是 `resolve` 而非 `reject`，超时后整体会"成功"而非失败，逻辑完全颠倒。

**常见坑：**
- 忘记 `clearTimeout` 导致定时器堆积（尤其在高频调用时）。
- 把 AbortController 与 race 混用但未正确处理 `AbortError`。

**面试小结：** 面试官期待你从"能用"到"健壮"的演进：先讲 race 原理，再主动暴露定时器泄漏与请求未取消两个问题，最后给出 AbortController 方案。能提到"finally 清理"是加分项。

Context 的核心心智模型是"广播-订阅"模式，而非"数据管道"。它解决的问题是 prop drilling——即 props 需要经过多层中间组件透传的繁琐问题。Context 让数据提供者（Provider）可以直接向任意深度的消费者（useContext）"广播"数据，中间组件无需感知和转发。

1. **广播模型三要素**：
   - **发射台**：`createContext` 创建 Context 对象，相当于定义了一个"频道"
   - **信号源**：`<Provider value={...}>` 包裹子树，相当于开台发射信号
   - **接收器**：`useContext(MyContext)` 在任意子组件中读取信号

   代码示例：
   ```jsx
   const ThemeContext = createContext('light');

   function App() {
     return (
       <ThemeContext.Provider value="dark">
         <Header />  {/* 中间组件不需要传递任何 props */}
       </ThemeContext.Provider>
     );
   }

   function Header() {
     return <Toolbar />;  // 不接触 ThemeContext
   }

   function Toolbar() {
     const theme = useContext(ThemeContext);  // 直接读取
     return <div>{theme}</div>;
   }
   ```

2. **与 prop drilling 的关系**：Context 不是完全替代 props，而是补充。官方建议："Before you use context, try passing props or passing JSX as children." 很多时候，问题不是"需要透传"，而是"组件拆分不合理"。比如：
   ```jsx
   // 不好的做法：强行用 Context 传一个只在两层内使用的数据
   // 好的做法：提取中间组件，让 props 只传一层
   ```

3. **"广播"的深层含义**：广播是推送式的——Provider 的 value 变化时，所有订阅者都会被"叫醒"（重渲染），不管他们是否关心变化的具体内容。这与"管道"（按需拉取）有本质区别。

**常见坑**：
- 误以为 Context 只重渲染"关心的部分"，实际上它重渲染所有订阅者
- 把 Context 当作全局状态管理工具（如 Redux 的替代品），过度使用导致组件复用性下降

**面试小结**：核心是理解广播模型的"推送"特性，以及 Context 解决的"透传"问题，而非"状态管理"问题。能区分"何时该用 Context"与"何时该重构组件"是加分项。

**核心结论**：`all` 在第一个 Promise 失败后立即 reject，但其他 Promise 仍在执行，其后续的 reject 可能无人监听，从而触发 `unhandledrejection` 全局警告。

**分点展开**：
1. **问题复现**：
```js
const p1 = Promise.reject('err1');
const p2 = new Promise((_, reject) => setTimeout(() => reject('err2'), 1000));
Promise.all([p1, p2]).catch(e => console.log('caught', e));
// p2 在 1 秒后 reject，但 all 已经因 p1 失败而结束，p2 的 rejection 无人处理
// → 触发 unhandledrejection 事件
```
2. **原因分析**：`all` 内部会为每个输入 Promise 绑定 then/catch，但快速失败后，它不再关心剩余 Promise 的状态——这些 Promise 的 rejection 就变成了"孤儿拒绝"。
3. **解决方案**：
   - **方案一：给每个 Promise 附加 catch**（推荐）：
   ```js
   const safeP2 = p2.catch(err => ({ error: err })); // 吞掉错误，all 只看成功值
   Promise.all([p1, safeP2]).then(...);
   ```
   - **方案二：全局监听 unhandledrejection**（兜底）：
   ```js
   window.addEventListener('unhandledrejection', e => {
     e.preventDefault(); // 阻止默认警告
     console.error('Unhandled rejection:', e.reason);
   });
   ```
   - **方案三：改用 `allSettled`**（如果业务允许部分失败）。
4. **最佳实践**：在并发请求中，如果某个 Promise 的失败可以被容忍，务必先给它加 `.catch(() => null)` 或转换为 `allSettled`，避免产生未处理拒绝。

**常见坑**：
- 在 Node.js 中，`unhandledrejection` 默认会直接抛出错误并终止进程（新版 Node 行为），比浏览器更严重。
- 给 Promise 加 catch 后，`all` 的失败语义会改变——需要自行判断 `null` 值代表失败。

**面试小结**：本题考察对"快速失败副作用"的认知。先复现问题，再给出三种解法，并强调"预防优于兜底"的工程思维。

**核心结论**：`calc()` 用于任意数值组合运算，`clamp(MIN, PREF, MAX)` 是响应式尺寸夹取的首选，`min()/max()` 分别取多值中的最小/最大值，四者配合可实现无断点的流式布局。

**分点展开**：
1. **函数定位**：
   - `calc()`：`width: calc(100% - 20px)`，支持 + - * /，可混合单位。
   - `clamp()`：`font-size: clamp(14px, 2vw, 20px)`，PREF 为理想值，浏览器自动夹取在 MIN/MAX 之间。
   - `min()`：`width: min(100%, 600px)` 取小值，常用于"不超过最大宽度"。
   - `max()`：`width: max(300px, 50%)` 取大值，常用于"至少保证最小宽度"。
2. **流式排版示例**：
   ```css
   h1 {
     font-size: clamp(1.5rem, 1rem + 3vw, 3rem);
     line-height: 1.2;
   }
   p {
     font-size: clamp(0.875rem, 0.75rem + 1vw, 1.125rem);
     max-width: 65ch;
   }
   .container {
     padding: clamp(12px, 2vw, 24px);
   }
   ```
3. **组合技巧**：`clamp()` 内部可嵌套 `calc()`，如 `clamp(14px, calc(1rem + 2vw), 24px)`。
4. **工程化意义**：减少媒体查询数量，实现"流体排版"（Fluid Typography），提升页面性能（减少重排）。

**常见坑**：`clamp()` 的 MIN 必须小于 MAX，否则浏览器取 MIN；`calc()` 内 `+` 和 `-` 两侧必须留空格，`*` 和 `/` 不需要；`min()/max()` 中若含 `calc()`，可省略内层 `calc()` 直接写表达式。

**面试小结**：先明确四者定位，再给出包含字号、内边距的流式排版示例，最后指出运算符号空格等易错细节，展示对 CSS 数学函数的熟练掌握。

**核心结论**：var 在整个循环中共享同一个函数级作用域绑定，循环结束后 i 为 3，所有回调读取同一个 i；let 每次迭代创建独立的块级绑定，回调捕获各自迭代的 i 值。

1. **var 版本**：
```js
for (var i = 0; i < 3; i++) {
  setTimeout(() => console.log(i));
}
// 输出：3 3 3
```
- var 声明提升到函数作用域顶部，整个循环只有一个 i 变量。
- 循环结束后 i = 3，三个 setTimeout 回调执行时读取同一个 i。

2. **let 版本**：
```js
for (let i = 0; i < 3; i++) {
  setTimeout(() => console.log(i));
}
// 输出：0 1 2
```
- let 声明在循环体内创建块级作用域，每次迭代都会**重新绑定**一个新的 i。
- 每个回调闭包捕获的是自己迭代的 i 副本。

3. **底层机制**：ES2015 规范规定 for 循环的 let 声明在每次迭代时执行"创建新绑定 + 复制上一轮值"的语义（CreatePerIterationEnvironment）。

**常见坑**：
- 若在循环体内用 `let` 但回调是同步执行，则无差异。
- 老代码用 IIFE 模拟块级作用域：`(function(j){ setTimeout(() => console.log(j)); })(i);`

**面试小结**：这是"闭包捕获变量"与"作用域绑定生命周期"的经典考题。var 捕获的是变量本身，let 捕获的是每次迭代的值快照。

**核心结论**：`history.state` 是当前历史记录的 state（只读），`event.state` 是 `popstate` 触发时目标历史记录的 state；两者在大多数场景下值相同，但语义不同，可用于实现状态持久化。

- **区别详解**：
  - `history.state`：访问当前页面关联的 state，不触发任何事件，任何时候可读。
  - `event.state`：仅在 `popstate` 回调中可用，是导航目标记录的 state。
  - 示例：当前在 `/page2`（state 为 `{page:2}`），后退到 `/page1`（state 为 `{page:1}`），此时 `history.state` 已变为 `{page:1}`，而 `event.state` 也是 `{page:1}`。
- **状态持久化方案**：
  1. **轻量状态**：直接存入 state 对象，如 `{ pageId: 2, filter: 'all' }`。
  2. **重量数据**：state 中只存 ID，实际数据从 `sessionStorage` 或全局 store 读取。
  3. **URL 参数**：将关键参数拼在 URL 中，如 `/list?page=2&sort=desc`，刷新后可从 `location.search` 恢复。
- **代码示例**：
  ```js
  // 进入列表页
  history.pushState({ listPage: 2 }, '', '/list?page=2');
  // 后退恢复
  window.addEventListener('popstate', (e) => {
    const page = e.state?.listPage || 1;
    fetchList(page);
  });
  ```

**常见坑**：state 对象不能存函数、DOM 元素等不可序列化内容；不同浏览器对 state 大小有限制（通常 640KB 左右），超限会抛异常。

**面试小结**：此题考察对 History API 状态机制的精细理解。回答重点在于区分两个 API 的语义，并给出实用的状态持久化策略。

**核心结论**：`useContext` 只认"上方祖先"的 Provider，同一组件内既创建 Provider 又调用 `useContext` 是无效的；就近查找规则保证数据流是单向自顶向下的。

**分点展开**：
1. **就近查找规则**：React 官方文档说明 *"The component will use the value of the nearest `<LevelContext>` in the UI tree above it."*——查找方向是严格向上的，找到最近的 Provider 就停止；整条路径都没有 Provider 时，使用 `createContext(defaultValue)` 的默认值。
2. **Caveat 解读**：官方原文 *"`useContext()` call in a component is not affected by providers returned from the same component."* 意思是：如果组件 A 在其 return 中渲染了一个 `<MyContext.Provider>`，同时组件 A 内部又调用了 `useContext(MyContext)`，那么 A 读取到的值**不是**它自己渲染的那个 Provider 提供的值——因为那个 Provider 是 A 的"后代"，不在 A 的上方。
3. **错误示例**：
   ```jsx
   function App() {
     const [user, setUser] = useState(null);
     // 错误：App 自己渲染 Provider，自己又消费它
     const value = useContext(UserContext); // 这里拿到的是 defaultValue 或更上层的值
     return (
       <UserContext.Provider value={{ user, setUser }}>
         <Child />
       </UserContext.Provider>
     );
   }
   ```
   正确做法是：App 只负责提供 Provider，消费行为必须发生在 Provider 的**后代**组件中。
4. **实际影响**：这个规则保证了数据流方向清晰——只有位于 Provider 下方的组件才能消费该值，避免了"自我提供、自我消费"的循环依赖。

**常见坑**：
- 在同一个组件中既提供又消费 Context，导致拿到的是默认值而非自己设置的值，bug 难以排查。
- 将 Provider 放在组件树的"中间层"而非顶层，导致上层组件无法消费。

**面试小结**：此题考察对 Context 数据流方向的精确理解。回答时用"上方祖先"这个关键词，配合错误示例，能体现对官方文档的深度掌握。

核心结论：`will-change` 是提示浏览器提前将元素提升为独立合成层并做优化准备，但滥用会导致图层爆炸与内存飙升，应遵循"最小化、临时化、目标化"原则。

**分点展开：**
1. **作用机制**：`will-change: transform` 告诉浏览器该元素即将发生 transform 变化，浏览器会提前将其提升为独立合成层，避免动画启动时的首帧卡顿。
2. **正确使用方式**：
   - 在动画开始前添加，动画结束后移除（可用 `animationend` 事件）。
   - 只对真正需要动画的元素使用，且属性值尽量具体（如 `will-change: transform` 而非 `will-change: all`）。
   - 数量控制在 3-5 个以内。
3. **滥用后果**：每个合成层都占用 GPU 内存（纹理存储），几十个元素加 `will-change` 会导致内存暴涨、移动端崩溃；且图层增多会增加合成器合并开销。
4. **与 `translateZ(0)` 的关系**：`translateZ(0)` 是经典的"hack"方式，利用 3D 变换强制创建合成层，效果与 `will-change: transform` 类似但更隐晦，且无法表达意图。现代浏览器推荐直接用 `will-change`。
5. **代码示例**：
   ```css
   .animated-card {
     will-change: transform;
   }
   .animated-card.animating {
     animation: slide 0.3s ease;
   }
   /* 动画结束后移除 will-change */
   ```

**常见坑**：`will-change` 不是性能银弹，它只是优化提示；若元素本身不复杂，提升图层反而增加开销。

**面试小结**：强调"提前优化 vs 实际优化"的权衡，展示对 GPU 内存成本与合成器开销的量化意识。

`children` 透传是一种**反向控制**的组件组合模式——父组件决定"渲染什么"，子组件决定"在哪里渲染"。它能让中间组件完全解耦，比 Context 更显式、更可预测。当数据只在一两个层级内传递时，children 往往是更优解。

1. **核心思想**：与其把数据层层透传，不如把"使用数据的 JSX"直接作为 children 传入目标组件。

   ```jsx
   // ❌ 用 Context 的过度设计
   const UserContext = createContext(null);
   function Page() {
     const user = { name: 'Alice' };
     return (
       <UserContext.Provider value={user}>
         <Layout />
       </UserContext.Provider>
     );
   }
   function Layout() {
     return <><Sidebar /><Content /></>;
   }
   function Content() {
     const user = useContext(UserContext);  // 只为了拿 user
     return <UserProfile user={user} />;
   }

   // ✅ 用 children 的优雅方案
   function Page() {
     const user = { name: 'Alice' };
     return (
       <Layout
         content={<UserProfile user={user} />}  // 直接传入 JSX
       />
     );
   }
   function Layout({ content }) {
     return <><Sidebar />{content}</>;
   }
   ```

2. **适用场景判断**：
   - 数据只被**一个或少数**组件使用 → children 更合适
   - 数据需要被**多个不同分支**的深层组件使用 → Context 更合适
   - 中间组件只是"过路"（不关心数据） → children 让它们完全无感知
   - 中间组件需要**灵活决定**子组件的位置 → children 天然支持

3. **官方建议原文**："Before you use context, try passing props or passing JSX as children." 这暗示了一个常见问题：开发者遇到 prop drilling 时，第一反应是"上 Context"，但往往真正的问题是**组件拆分不合理**——中间组件本可以接受 children 而不是自己拼装。

**常见坑**：
- 把 children 方案强行用于"数据需要跨 5 层以上且多分支"的场景，导致 JSX 嵌套过深、可读性下降
- 忽略 children 方案的"静态性"——如果数据频繁变化，每次都要重新构造 JSX，可能不如 Context 直观

**面试小结**：核心是理解 children 是"数据跟随 JSX 走"的显式方案，Context 是"数据广播"的隐式方案。能根据"数据使用范围"和"中间组件职责"做出正确选择，是考察重点。

**核心结论**：props 随时间变化（父组件重渲染产生新 props），但每次渲染中 props 对象不可变；子组件不能修改 props，只能通过回调或 state 间接影响父组件。

**分点展开**：
1. **"会变"的含义**：父组件状态更新 → 触发重渲染 → 生成新的 props 对象传给子组件。子组件在两次渲染中看到的 props 引用不同，内容可能不同。
2. **"不可变"的含义**：在单次渲染内，props 对象及其属性是只读的。React 在开发模式会冻结 props 对象（Object.freeze），严格模式下修改会抛错。
3. **父组件改变 props 的方式**：
   ```jsx
   function Parent() {
     const [count, setCount] = useState(0);
     return <Child count={count} onIncrement={() => setCount(c => c + 1)} />;
   }
   ```
   父组件通过 setState 更新状态，React 重新渲染时传入新 props。
4. **子组件"修改" props 的正确替代**：
   - **回调函数**：子组件调用父组件传入的 `onXxx` 函数，请求父组件更新状态。
   - **派生 state**：`const [prevProps, setPrevProps] = useState(props); if (prevProps !== props) { /* 同步 */ }`（不推荐，用 key 更佳）。
   - **受控组件**：子组件不持有状态，完全由父组件通过 props 控制。
5. **反模式示例**：
   ```jsx
   // ❌ 错误：直接修改 props
   function Child({ items }) {
     items.push('new'); // 修改了父组件的数组
   }
   // ✅ 正确：复制后修改
   function Child({ items }) {
     const newItems = [...items, 'new']; // 本地副本
   }
   ```

**常见坑**：
- 修改 props 嵌套对象（如 `props.user.name = 'x'`）不会报错但不会触发更新，产生"静默失败"。
- 在 useEffect 中依赖 props 但忘记在依赖数组中加入，导致闭包捕获旧值。

**面试小结**：此题是 React 核心概念的经典考题。回答时用"时间维度"区分"会变"与"不可变"，再给出三种替代方案，展示对受控组件模式的理解。

**每次调用外层函数时，都会创建一个全新的词法环境，闭包绑定的是当次调用的环境——不同调用产生的闭包互不共享变量。**

**验证示例：**
```js
function counter() {
  let n = 0;
  return {
    increment: () => ++n,
    get: () => n
  };
}

const a = counter();
const b = counter();

a.increment(); // a 的 n 变为 1
a.increment(); // a 的 n 变为 2
b.increment(); // b 的 n 变为 1

console.log(a.get()); // 2
console.log(b.get()); // 1
console.log(a.get() === b.get()); // false
```

**深入机制：**

1. **词法环境（Lexical Environment）**
   - 每次调用 `counter()` 创建一个新的环境记录（Environment Record）
   - 返回的对象方法持有对该环境记录的引用

2. **独立性证明**
   - `a` 和 `b` 的 `n` 是不同内存位置的值
   - 修改 `a` 的 `n` 不影响 `b` 的 `n`
   - 这类似"每次实例化一个类"——闭包是"轻量级对象"

3. **对比：共享闭包**
   ```js
   // 如果只调用一次外层函数，所有闭包共享同一环境
   const shared = counter();
   const f1 = shared.increment;
   const f2 = shared.increment;
   f1(); f2(); // 共享同一个 n，最终为 2
   ```

**常见坑：**
- 误以为"闭包"是单个对象——实际是"函数 + 环境"的组合，每次创建都不同
- 混淆"闭包创建"与"闭包调用"——创建时绑定环境，调用时读取当前值

**面试小结：** 用计数器示例清晰展示独立性，再对比"共享环境"的情况，说明闭包创建机制的本质。

**核心结论：自定义 Hook 共享的是“有状态逻辑的写法”，而非状态本身；每次调用都会创建完全独立的状态容器。**

1. **菜谱与菜的比喻**：菜谱（自定义 Hook）定义了烹饪步骤（逻辑），但每口锅（组件实例）炒出的菜（状态）是独立的。`useOnlineStatus` 在两个组件中被调用，各自维护自己的 `isOnline` 状态，互不干扰。
2. **官方定义锚定**：React 官方明确 *"Custom Hooks let you share stateful logic, not state itself"*——共享的是逻辑（如何管理状态、副作用、缓存），而非状态数据。
3. **机制级解释**：每次调用自定义 Hook 时，其内部的所有 `useState`/`useEffect` 等都会被注册到当前组件独立的 Fiber 节点上。两个组件调用同一 Hook，会分别创建两组独立的 Hook 链表。
4. **代码验证**：
   ```jsx
   // useCounter.js
   export function useCounter(initial = 0) {
     const [count, setCount] = useState(initial);
     const increment = () => setCount(c => c + 1);
     return { count, increment };
   }
   // A 组件和 B 组件各自调用，count 互不影响
   ```
5. **与普通函数对比**：普通函数共享全局变量会导致污染；自定义 Hook 通过 React 的 Hook 机制天然隔离状态，无需额外做闭包或单例处理。

**常见坑**：误以为自定义 Hook 是“共享状态”的工具，试图用它实现跨组件通信——这违背设计意图，应使用 Context 或状态管理库。

**面试小结**：此题考察对自定义 Hook 本质的理解。回答时先点明“逻辑共享、状态隔离”，再用官方引用和代码示例佐证，最后指出常见误用场景，体现深度。

**核心结论**：代码分割的核心原理是将单一 JS bundle 拆分为多个独立 chunk，通过动态 import() 在运行时按需加载，从而减少首屏需要下载、解析和执行的代码量。动态 import() 之所以是关键，是因为它向构建工具提供了明确的"分割点"信号。

**分点展开**：
1. **原理机制**：构建工具（webpack/Vite/Rollup）在编译时遇到动态 import() 语法，会将其引用的模块及其依赖树单独打包成一个独立 chunk 文件。运行时，当代码执行到该 import() 语句时，浏览器才会发起 HTTP 请求获取该 chunk。
2. **webpack 实现**：webpack 通过 `SplitChunksPlugin` 自动处理动态导入的分割，同时支持通过 `optimization.splitChunks` 配置手动控制 vendor、公共模块的拆分策略。生成的 chunk 文件通过 JSONP 或 `<script>` 标签动态注入加载。
3. **Vite 实现**：Vite 基于 Rollup，在构建阶段同样识别动态 import() 并拆包。开发环境利用原生 ES Module 按需加载，生产环境则通过 Rollup 的 `output.manualChunks` 选项控制分割策略。
4. **运行时加载**：浏览器加载 chunk 后，会缓存该模块；后续再次 import() 同一模块时直接命中缓存，不会重复请求。

**代码示例**：
```js
// 动态导入 → 构建后生成独立 chunk
button.addEventListener('click', async () => {
  const { default: chartLib } = await import('./heavy-chart-lib');
  chartLib.render();
});
```

**常见坑**：
- 动态 import() 的路径必须是静态字符串或有限变量，不能完全动态拼接，否则构建工具无法静态分析出依赖关系。
- 过度分割导致大量小 chunk，HTTP/2 下虽可并行，但仍有请求开销和缓存碎片化问题。

**面试小结**：回答时先讲清"构建时拆包 + 运行时按需加载"的双阶段模型，再说明动态 import() 如何为构建工具提供分割信号，最后可补充 HTTP/2 对拆包粒度的影响。

