```js
function animate() {
  const start = Date.now();
  const duration = 1000;
  const el = document.getElementById('box');
  function frame() {
    const elapsed = Date.now() - start;
    const progress = Math.min(elapsed / duration, 1);
    el.style.left = progress * 100 + 'px';
    if (progress < 1) setTimeout(frame, 16.7);
