     {"type": "function", "function": {
       "name": "get_weather", "description": "查询指定日期和城市的天气",
       "parameters": {"type": "object", "properties": {
         "city": {"type": "string"}, "date": {"type": "string", "format": "date"}
       }, "required": ["city", "date"]}
     }},
     {"type": "function", "function": {
       "name": "add_calendar_reminder", "description": "添加日历提醒",
       "parameters": {"type": "object", "properties": {
